import React, { useEffect, useState } from "react";
import Button from "react-bootstrap/Button";
import Table from "react-bootstrap/Table";
import Form from "react-bootstrap/Form";
import { collection, getDocs, deleteDoc, doc, updateDoc } from "firebase/firestore";
import { db } from "./firebase";
import { normalizzaCliente } from "./utils/normalizza";
import { normalizzaClientiFirebase } from "./utils/normalizzaClientiFirebase";
import { toast } from "react-toastify";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";
import { SafeRow } from "./components/CSVImporter";
import CsvExport from "./CsvExport";

function ClientiTable() {
  const [clienti, setClienti] = useState([]);
  const [filtro, setFiltro] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [modifica, setModifica] = useState({});

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const dati = snapshot.docs.map(doc => ({
          id: doc.id,
          ...(typeof normalizzaCliente === "function"
            ? normalizzaCliente(doc.data())
            : doc.data())
        }));
        setClienti(dati);
      } catch (error) {
        console.error("Errore nel caricamento clienti:", error);
        toast.error("❌ Errore nel caricamento dei clienti");
      }
    };
    fetchClienti();
  }, []);

  const intestazioni = [
    { label: "Ragione Sociale", key: "ragioneSociale" },
    { label: "Email", key: "email" },
    { label: "Telefono", key: "telefono" },
    { label: "Indirizzo", key: "indirizzo" },
    { label: "Referente", key: "referente" }
  ];

  const filtrati = clienti.filter(c =>
    [c.ragioneSociale, c.email, c.telefono, c.referente]
      .filter(Boolean)
      .some(val => val.toLowerCase().includes(filtro.toLowerCase()))
  );

  const stampaTabella = () => window.print();

  const esportaExcel = () => {
    const dati = filtrati.map(c => ({
      "Ragione Sociale": c.ragioneSociale || "",
      "Email": c.email || "",
      "Telefono": c.telefono || "",
      "Indirizzo": c.indirizzo || "",
      "Referente": c.referente || ""
    }));
    const ws = XLSX.utils.json_to_sheet(dati);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Clienti");
    XLSX.writeFile(wb, "clienti.xlsx");
  };

  const eliminaCliente = async (id, nome) => {
    if (!window.confirm(`Vuoi eliminare il cliente "${nome}"?`)) return;
    try {
      await deleteDoc(doc(db, "CLIENTI", id));
      setClienti(prev => prev.filter(c => c.id !== id));
      toast.success(`🗑️ Cliente "${nome}" eliminato`);
    } catch (error) {
      console.error("Errore nell'eliminazione:", error);
      toast.error("❌ Errore nell'eliminazione");
    }
  };

  const avviaModifica = (cliente) => {
    setEditingId(cliente.id);
    setModifica({ ...cliente });
  };

  const salvaModifiche = async () => {
    try {
      await updateDoc(doc(db, "CLIENTI", editingId), modifica);
      setClienti(prev =>
        prev.map(c => (c.id === editingId ? { ...c, ...modifica } : c))
      );
      toast.success("✅ Cliente aggiornato");
      setEditingId(null);
      setModifica({});
    } catch (error) {
      console.error("Errore salvataggio:", error);
      toast.error("❌ Errore nel salvataggio");
    }
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h3>👥 Elenco Clienti</h3>
        <div className="d-flex gap-2">
          <CsvExport
            dati={filtrati}
            intestazioni={intestazioni}
            nomeFile="clienti.csv"
          />
          <Button variant="outline-success" onClick={esportaExcel}>
            📤 Excel
          </Button>
          <Button variant="outline-secondary" onClick={stampaTabella}>
            🖨️ Stampa
          </Button>
          <Button variant="warning" onClick={normalizzaClientiFirebase}>
            🧹 Normalizza Clienti
          </Button>
        </div>
      </div>

      <Form.Control
        type="text"
        className="mb-3"
        placeholder="🔍 Cerca per nome, email, telefono o referente..."
        value={filtro}
        onChange={(e) => setFiltro(e.target.value)}
      />

      <Table bordered hover>
        <thead className="table-light">
          <tr>
            <th>Ragione Sociale</th>
            <th>Email</th>
            <th>Telefono</th>
            <th>Indirizzo</th>
            <th>Referente</th>
            <th>Azioni</th>
          </tr>
        </thead>
        <tbody>
          {filtrati.length > 0 ? (
            filtrati.map((c) => (
              <tr key={c.id}>
                {editingId === c.id ? (
                  <>
                    <td>
                      <Form.Control
                        size="sm"
                        value={modifica.ragioneSociale || ""}
                        onChange={(e) =>
                          setModifica({ ...modifica, ragioneSociale: e.target.value })
                        }
                      />
                    </td>
                    <td>
                      <Form.Control
                        size="sm"
                        value={modifica.email || ""}
                        onChange={(e) =>
                          setModifica({ ...modifica, email: e.target.value })
                        }
                      />
                    </td>
                    <td>
                      <Form.Control
                        size="sm"
                        value={modifica.telefono || ""}
                        onChange={(e) =>
                          setModifica({ ...modifica, telefono: e.target.value })
                        }
                      />
                    </td>
                    <td>
                      <Form.Control
                        size="sm"
                        value={modifica.indirizzo || ""}
                        onChange={(e) =>
                          setModifica({ ...modifica, indirizzo: e.target.value })
                        }
                      />
                    </td>
                    <td>
                      <Form.Control
                        size="sm"
                        value={modifica.referente || ""}
                        onChange={(e) =>
                          setModifica({ ...modifica, referente: e.target.value })
                        }
                      />
                    </td>
                    <td className="d-flex gap-2">
                      <Button size="sm" variant="success" onClick={salvaModifiche}>
                        💾 Salva
                      </Button>
                      <Button size="sm" variant="secondary" onClick={() => setEditingId(null)}>
                        ❌ Annulla
                      </Button>
                    </td>
                  </>
                ) : (
                  <>
                    <SafeRow row={c} />
                    <td className="d-flex gap-2">
                      <Button
                        size="sm"
                        variant="outline-primary"
                        onClick={() => avviaModifica(c)}
                      >
                        ✏️ Modifica
                      </Button>
                      <Button
                        size="sm"
                        variant="outline-danger"
                        onClick={() => eliminaCliente(c.id, c.ragioneSociale)}
                      >
                        🗑️ Elimina
                      </Button>
                    </td>
                  </>
                )}
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="6" className="text-center text-muted">
                Nessun cliente trovato.
              </td>
            </tr>
          )}
        </tbody>
      </Table>
    </div>
  );
}

export default ClientiTable;