import React, { useEffect, useState } from "react";
import { collection, onSnapshot, updateDoc, doc, getDoc } from "firebase/firestore";
import { db } from "./firebase";
import { useAuth } from "./AuthContext";
import Table from "react-bootstrap/Table";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import toast from "react-hot-toast";

const DashboardTecnico = () => {
  const { user } = useAuth();
  const [interventi, setInterventi] = useState([]);
  const [mezzi, setMezzi] = useState({});
  const [noteMap, setNoteMap] = useState({});

  useEffect(() => {
    if (!user?.uid) return;

    const unsubscribe = onSnapshot(collection(db, "INTERVENTI"), async (snapshot) => {
      const lista = snapshot.docs
        .map((doc) => ({ id: doc.id, ...doc.data() }))
        .filter((i) => i.tecnicoAssegnatoId === user.uid);

      const mezzoIds = [...new Set(lista.map((i) => i.mezzoId).filter(Boolean))];
      const mezzoData = {};

      for (const id of mezzoIds) {
        const ref = doc(db, "MEZZI", id);
        const snap = await getDoc(ref);
        if (snap.exists()) mezzoData[id] = snap.data();
      }

      setMezzi(mezzoData);
      setInterventi(lista);
    });

    return () => unsubscribe();
  }, [user?.uid]);

  const aggiornaStato = async (id, nuovoStato) => {
    const note = noteMap[id] || "";
    if ((nuovoStato === "attesa_ricambi" || nuovoStato === "conclusa") && note.trim() === "") {
      toast.error("✏️ Inserisci le note prima di aggiornare lo stato");
      return;
    }

    try {
      const ref = doc(db, "INTERVENTI", id);
      await updateDoc(ref, {
        statoTecnico: nuovoStato,
        noteTecnico: note,
        updatedAt: new Date()
      });
      toast.success("✅ Stato aggiornato");
    } catch (error) {
      toast.error("❌ Errore aggiornamento");
    }
  };

  if (!user?.uid) return <div className="p-4 text-danger">⚠️ Utente non autenticato</div>;

  return (
    <div className="p-4">
      <h3 className="mb-3">🔧 Interventi Assegnati</h3>
      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>Cliente</th>
            <th>Mezzo</th>
            <th>Categoria</th>
            <th>Data</th>
            <th>Note Tecnico</th>
            <th>Stato</th>
            <th>Azioni</th>
          </tr>
        </thead>
        <tbody>
          {interventi.map((i) => {
            const mezzo = mezzi[i.mezzoId];
            return (
              <tr key={i.id}>
                <td>{i.ragioneSociale || "—"}</td>
                <td>{mezzo ? `${mezzo.marca} ${mezzo.modello}` : "—"}</td>
                <td>{i.categoria}</td>
                <td>{i.dataIntervento ? new Date(i.dataIntervento.seconds * 1000).toLocaleDateString() : "—"}</td>
                <td>
                  <Form.Control
                    as="textarea"
                    rows={2}
                    value={noteMap[i.id] || ""}
                    onChange={(e) => setNoteMap({ ...noteMap, [i.id]: e.target.value })}
                    placeholder="Note tecniche..."
                  />
                </td>
                <td>{i.statoTecnico || "assegnato"}</td>
                <td className="d-flex flex-column gap-1">
                  <Button variant="outline-primary" size="sm" onClick={() => aggiornaStato(i.id, "accettata")}>
                    ✅ Accetta
                  </Button>
                  <Button variant="outline-warning" size="sm" onClick={() => aggiornaStato(i.id, "attesa_ricambi")}>
                    🛠️ In attesa ricambi
                  </Button>
                  <Button variant="outline-success" size="sm" onClick={() => aggiornaStato(i.id, "conclusa")}>
                    ✔️ Concluso
                  </Button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </Table>
    </div>
  );
};

export default DashboardTecnico;