import React, { useState } from "react";
import { createUserWithEmailAndPassword } from "firebase/auth";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import { auth, db } from "../firebase";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import toast from "react-hot-toast";

const CreaUtenteForm = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [ruolo, setRuolo] = useState("");
  const [nome, setNome] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!email || !password || !ruolo || !nome) {
      toast.error("❌ Compila tutti i campi");
      return;
    }

    setLoading(true);

    try {
      const credenziali = await createUserWithEmailAndPassword(auth, email, password);
      const nuovoUtente = credenziali.user;

      await addDoc(collection(db, "UTENTI"), {
        uid: nuovoUtente.uid,
        email: nuovoUtente.email,
        ruolo,
        nome,
        attivo: true,
        dataCreazione: Timestamp.now(),
      });

      toast.success("✅ Utente creato correttamente");
      setEmail("");
      setPassword("");
      setRuolo("");
      setNome("");
    } catch (error) {
      console.error("Errore creazione utente:", error);
      toast.error("❌ Errore durante la creazione");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Form onSubmit={handleSubmit} className="p-4 border rounded bg-light mt-5">
      <h5 className="mb-3">➕ Crea nuovo Utente</h5>

      <Form.Group className="mb-3">
        <Form.Label>Nome *</Form.Label>
        <Form.Control
          type="text"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
          required
        />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Email *</Form.Label>
        <Form.Control
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Password *</Form.Label>
        <Form.Control
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Ruolo *</Form.Label>
        <Form.Select
          value={ruolo}
          onChange={(e) => setRuolo(e.target.value)}
          required
        >
          <option value="">Seleziona ruolo</option>
          <option value="admin">Admin</option>
          <option value="tecnico">Tecnico</option>
          <option value="cliente">Cliente</option>
        </Form.Select>
      </Form.Group>

      <Button type="submit" variant="primary" disabled={loading}>
        {loading ? "⏳ Creazione..." : "✅ Crea Utente"}
      </Button>
    </Form>
  );
};

export default CreaUtenteForm;