import React from "react";
import { Link, useLocation } from "react-router-dom";
import { useAuth } from "../AuthContext";
import {
  FaHome, FaUsers, FaTools, FaClipboardList,
  FaMapMarkedAlt, FaChartBar, FaUserCog, FaKey
} from "react-icons/fa";
import "./Sidebar.css";

const Sidebar = () => {
  const { ruolo } = useAuth();
  const location = useLocation();
  const isActive = (path) => location.pathname === path;

  const menuAdmin = [
    { label: "Dashboard", path: "/", icon: <FaHome /> },
    { label: "Clienti", path: "/clienti", icon: <FaUsers /> },
    { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
    { label: "Utenti", path: "/utenti", icon: <FaUserCog /> },
    { label: "Log attività", path: "/log", icon: <FaClipboardList /> },
    { label: "Statistiche", path: "/statistiche", icon: <FaChartBar /> },
    { label: "Mappa", path: "/mappa", icon: <FaMapMarkedAlt /> },
  ];

  const menuTecnico = [
    { label: "Dashboard", path: "/", icon: <FaHome /> },
    { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
    { label: "Mappa", path: "/mappa", icon: <FaMapMarkedAlt /> },
  ];

  const menuComune = [
    { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
    { label: "Cambio Password", path: "/recupero", icon: <FaKey /> },
  ];

  const menu = ruolo === "admin" ? menuAdmin : ruolo === "tecnico" ? menuTecnico : [];

  return (
    <div className="sidebar">
      <img src={`${process.env.PUBLIC_URL}/logo.png`} alt="Logo Aziendale" className="sidebar-logo" />
      <div className="sidebar-title">Menù {ruolo}</div>
      <nav className="sidebar-nav">
        {[...menu, ...menuComune].map((item) => (
          <Link
            key={item.path}
            to={item.path}
            className={isActive(item.path) ? "active" : ""}
          >
            <span style={{ marginRight: "0.5rem" }}>{item.icon}</span>
            {item.label}
          </Link>
        ))}
      </nav>
    </div>
  );
};

export default Sidebar;