import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../firebase";
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from "recharts";

const StatisticheInterventi = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const snapshot = await getDocs(collection(db, "INTERVENTI"));
      const lista = snapshot.docs.map((doc) => doc.data());
      setInterventi(lista);
    };
    fetchData();
  }, []);

  // 📊 Interventi per mese
  const perMese = Array.from({ length: 12 }, (_, i) => ({
    mese: new Date(0, i).toLocaleString("it-IT", { month: "short" }),
    totale: interventi.filter((i) => {
      const d = i.dataIntervento?.seconds;
      return d && new Date(d * 1000).getMonth() === i;
    }).length,
  }));

  // 📊 Interventi per categoria
  const perCategoria = ["manutenzione", "installazione", "assistenza"].map((cat) => ({
    categoria: cat,
    totale: interventi.filter((i) => i.categoria === cat).length,
  }));

  // 📊 Interventi per tecnico
  const tecnici = [...new Set(interventi.map((i) => i.tecnicoAssegnatoId).filter(Boolean))];
  const perTecnico = tecnici.map((t) => ({
    tecnico: t,
    totale: interventi.filter((i) => i.tecnicoAssegnatoId === t).length,
  }));

  const colori = ["#0d6efd", "#198754", "#ffc107", "#dc3545", "#6f42c1"];

  return (
    <div className="mt-5">
      <h4 className="mb-4">📈 Statistiche Interventi</h4>

      <div className="row">
        <div className="col-md-6 mb-4">
          <h5>Interventi per mese</h5>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={perMese}>
              <XAxis dataKey="mese" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="totale" fill="#0d6efd" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="col-md-6 mb-4">
          <h5>Interventi per categoria</h5>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={perCategoria}
                dataKey="totale"
                nameKey="categoria"
                cx="50%"
                cy="50%"
                outerRadius={100}
                label
              >
                {perCategoria.map((_, i) => (
                  <Cell key={i} fill={colori[i % colori.length]} />
                ))}
              </Pie>
              <Legend />
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="col-md-12 mb-4">
          <h5>Interventi per tecnico</h5>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={perTecnico}>
              <XAxis dataKey="tecnico" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="totale" fill="#198754" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default StatisticheInterventi;