import React from "react";

/**
 * Visualizza una data formattata in italiano.
 * @param {Object} props
 * @param {Date|Timestamp} props.data
 */
const DateDisplay = ({ data }) => {
  if (!data || typeof data.toDate !== "function") return <span>—</span>;
  const dateObj = data.toDate();
  return <span>{dateObj.toLocaleDateString("it-IT")}</span>;
};

export default DateDisplay;