import React, { useState } from "react";
import {
  collection,
  query,
  where,
  getDocs,
  addDoc,
  Timestamp,
} from "firebase/firestore";
import { db } from "./firebase";
import toast from "react-hot-toast";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import AutocompleteClienti from "./components/AutocompleteClienti";

const NuovaChiamataForm = () => {
  const [formData, setFormData] = useState({
    ragioneSociale: "",
    indirizzo: "",
    città: "",
    provincia: "",
    categoria: "",
    noteTecnico: "",
    mezzoId: "",
  });

  const [frequenza, setFrequenza] = useState("");
  const [dataIntervento, setDataIntervento] = useState("");
  const [mezziCliente, setMezziCliente] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value,
    }));
  };

  const handleSelectCliente = async (cliente) => {
    setFormData((prev) => ({
      ...prev,
      ragioneSociale: cliente.ragioneSociale || "",
      indirizzo: cliente.indirizzo || "",
      città: cliente.comune || "",
      provincia: cliente.provincia || "",
      mezzoId: "",
    }));

    try {
      const codiceInterno = cliente.codiceInterno;
      const q = query(
        collection(db, "MEZZI"),
        where("codiceInterno", "==", codiceInterno)
      );
      const snapshot = await getDocs(q);
      const listaMezzi = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
      setMezziCliente(listaMezzi);
    } catch (error) {
      console.error("Errore nel caricamento mezzi:", error);
      toast.error("❌ Errore durante il recupero dei mezzi");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const { ragioneSociale, indirizzo, città, provincia, categoria, mezzoId } = formData;

    if (!ragioneSociale || !indirizzo || !città || !provincia || !categoria || !dataIntervento || !mezzoId) {
      toast.error("❌ Compila tutti i campi obbligatori");
      return;
    }

    let prossimoIntervento = null;

    if (categoria === "manutenzione" && frequenza && dataIntervento) {
      const baseDate = new Date(dataIntervento);
      if (frequenza === "trimestrale") {
        baseDate.setMonth(baseDate.getMonth() + 3);
      } else if (frequenza === "annuale") {
        baseDate.setFullYear(baseDate.getFullYear() + 1);
      }
      prossimoIntervento = Timestamp.fromDate(baseDate);
    }

    setLoading(true);

    try {
      await addDoc(collection(db, "INTERVENTI"), {
        ...formData,
        statoTecnico: "assegnato",
        dataIntervento: Timestamp.fromDate(new Date(dataIntervento)),
        frequenza: frequenza || null,
        prossimoIntervento: prossimoIntervento || null,
        terminato: false,
      });

      toast.success("✅ Chiamata inserita correttamente");
      setFormData({
        ragioneSociale: "",
        indirizzo: "",
        città: "",
        provincia: "",
        categoria: "",
        noteTecnico: "",
        mezzoId: "",
      });
      setFrequenza("");
      setDataIntervento("");
      setMezziCliente([]);
    } catch (error) {
      console.error("Errore inserimento:", error);
      toast.error("❌ Errore durante l'inserimento");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Form onSubmit={handleSubmit} className="mb-4">
      <h4 className="mb-3">📞 Inserisci nuova chiamata</h4>

      <Form.Group className="mb-3">
        <Form.Label>Ragione Sociale *</Form.Label>
        <AutocompleteClienti onSelect={handleSelectCliente} />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Indirizzo *</Form.Label>
        <Form.Control
          type="text"
          name="indirizzo"
          value={formData.indirizzo}
          onChange={handleChange}
          required
        />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Comune *</Form.Label>
        <Form.Control
          type="text"
          name="città"
          value={formData.città}
          onChange={handleChange}
          required
        />
      </Form.Group>

      <Form.Group className="mb-3">
        <Form.Label>Provincia *</Form.Label>
        <Form.Control
          type="text"
          name="provincia"
          value={formData.provincia}
          onChange={handleChange}
          required
        />
      </Form.Group>

      {mezziCliente.length > 0 && (
        <Form.Group className="mb-3">
          <Form.Label>Mezzo associato *</Form.Label>
          <Form.Select
            name="mezzoId"
            value={formData.mezzoId}
            onChange={handleChange}
            required
          >
            <option value="">Seleziona mezzo</option>
            {mezziCliente.map((mezzo) => (
              <option key={mezzo.id} value={mezzo.id}>
                {mezzo.marca} {mezzo.modello} - {mezzo.targa}
              </option>
            ))}
          </Form.Select>
        </Form.Group>
      )}

      <Form.Group className="mb-3">
        <Form.Label>Categoria *</Form.Label>
        <Form.Select
          name="categoria"
          value={formData.categoria}
          onChange={handleChange}
          required
        >
          <option value="">Seleziona categoria</option>
          <option value="manutenzione">Manutenzione</option>
          <option value="installazione">Installazione</option>
          <option value="assistenza">Assistenza</option>
        </Form.Select>
      </Form.Group>

      {formData.categoria === "manutenzione" && (
        <>
          <Form.Group className="mb-3">
            <Form.Label>Frequenza *</Form.Label>
            <Form.Select
              value={frequenza}
              onChange={(e) => setFrequenza(e.target.value)}
              required
            >
              <option value="">Seleziona frequenza</option>
              <option value="trimestrale">Trimestrale</option>
              <option value="annuale">Annuale</option>
            </Form.Select>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Data intervento *</Form.Label>
            <Form.Control
              type="date"
              value={dataIntervento}
              onChange={(e) => setDataIntervento(e.target.value)}
              required
            />
          </Form.Group>
        </>
      )}

      <Form.Group className="mb-3">
        <Form.Label>Note tecnico</Form.Label>
        <Form.Control
          as="textarea"
          rows={3}
          name="noteTecnico"
          value={formData.noteTecnico}
          onChange={handleChange}
        />
      </Form.Group>

      <Button type="submit" variant="success" disabled={loading}>
        {loading ? "⏳ Salvataggio..." : "📤 Inserisci Chiamata"}
      </Button>
    </Form>
  );
};

export default NuovaChiamataForm;