import { collection, getDocs, updateDoc } from "firebase/firestore";
import { db } from "../firebase"; // Adatta il percorso se serve

const normalizzaCliente = (cliente) => {
  return {
    ragioneSociale: cliente.ragioneSociale?.trim() || "",
    email: cliente.email?.trim() || "",
    telefono: cliente.telefono?.trim() || "",
    indirizzo: cliente.indirizzo?.trim() || "",
    referente: cliente.referente?.trim() || "",
  };
};

export const normalizzaClientiFirebase = async () => {
  try {
    const snapshot = await getDocs(collection(db, "CLIENTI"));
    const clienti = snapshot.docs.map(doc => ({
      id: doc.id,
      ref: doc.ref,
      ...doc.data()
    }));

    for (const cliente of clienti) {
      const datiPuliti = normalizzaCliente(cliente);
      await updateDoc(cliente.ref, datiPuliti);
      console.log(`✅ Cliente aggiornato: ${cliente.ragioneSociale}`);
    }

    console.log("🎉 Tutti i clienti sono stati normalizzati correttamente.");
  } catch (error) {
    console.error("❌ Errore nella normalizzazione clienti:", error);
  }
};