// ✅ Import sempre in cima
import { collection, getDocs, updateDoc, doc } from "firebase/firestore";
import { db } from "../firebase";
import axios from "axios";

// ✅ La tua API Key Google Maps
const GOOGLE_API_KEY = "AIzaSyCEioYKP8rJxdsztoQ3xnJiD27k-s5Pvsg";

/**
 * Geolocalizza un indirizzo usando Google Maps Geocoding API
 * @param {string} indirizzo - Indirizzo completo
 * @returns {Promise<{ latitudine: number, longitudine: number } | null>}
 */
const geolocalizzaIndirizzo = async (indirizzo) => {
  if (!indirizzo || typeof indirizzo !== "string" || indirizzo.trim().length < 5) {
    console.warn("⚠️ Indirizzo non valido:", indirizzo);
    return null;
  }

  try {
    const response = await axios.get("https://maps.googleapis.com/maps/api/geocode/json", {
      params: {
        address: indirizzo,
        key: GOOGLE_API_KEY,
      },
    });

    const results = response.data.results;
    if (!results || results.length === 0) {
      console.warn("⚠️ Nessuna coordinata trovata per:", indirizzo);
      return null;
    }

    const location = results[0].geometry.location;
    return {
      latitudine: Number(location.lat),
      longitudine: Number(location.lng),
    };
  } catch (error) {
    console.error("❌ Errore nella geolocalizzazione:", error.message);
    return null;
  }
};

/**
 * Normalizza e geolocalizza i clienti in Firestore
 * Aggiunge latitudine e longitudine se mancanti
 */
export const normalizzaEGeolocalizzaClienti = async () => {
  try {
    const snapshot = await getDocs(collection(db, "CLIENTI"));
    const clienti = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));

    for (const cliente of clienti) {
      const giàGeolocalizzato = cliente.latitudine && cliente.longitudine;
      if (giàGeolocalizzato) continue;

      const indirizzoCompleto = [
        cliente.indirizzo,
        cliente.cap,
        cliente.città,
        cliente.provincia,
        "Italia"
      ].filter(Boolean).join(", ");

      const coords = await geolocalizzaIndirizzo(indirizzoCompleto);

      if (coords) {
        await updateDoc(doc(db, "CLIENTI", cliente.id), coords);
        console.log(`✅ Geolocalizzato: ${cliente.ragioneSociale || cliente.id}`);
      } else {
        console.warn(`⚠️ Impossibile geolocalizzare: ${cliente.ragioneSociale || cliente.id}`);
      }
    }

    console.log("🎯 Geolocalizzazione completata.");
  } catch (error) {
    console.error("❌ Errore globale nella geolocalizzazione clienti:", error.message);
  }
};